import * as fs from 'node:fs';
import * as path from 'node:path';
import { execSync } from 'node:child_process';
import { JoyError, PlanResult } from './types.js';

export const GENERATED_BANNER =
  '// @generated by @montionugera/joy-cli — DO NOT EDIT';

export interface ApplyOptions {
  dryRun?: boolean;
  force?: boolean;
  check?: boolean;
  keepOnFail?: boolean;
  noVerify?: boolean;
  verifyCommands?: string[];
}

export interface ApplySummary {
  created: string[];
  overwritten: string[];
  edited: string[];
  diffs: Record<string, string>;
}

function formatSimpleDiff(relPath: string, before: string, after: string): string {
  if (before === after) return '';
  return `--- a/${relPath}\n+++ b/${relPath}\n@@\n+${after.split('\n').slice(0, 5).join('\n+')}${after.split('\n').length > 5 ? '\n+...' : ''}`;
}

export function applyPlan(
  cwd: string,
  plan: PlanResult,
  opts: ApplyOptions = {}
): ApplySummary {
  const summary: ApplySummary = {
    created: [],
    overwritten: [],
    edited: [],
    diffs: {},
  };

  // Phase 1: Validate all target files in memory before touching disk
  for (const item of plan.creates) {
    const absPath = path.join(cwd, item.relPath);
    const exists = fs.existsSync(absPath);

    if (opts.check) {
      if (!exists) {
        throw new JoyError(
          'E_DRIFT',
          `Generated file "${item.relPath}" is missing on disk.`,
          2
        );
      }
      const current = fs.readFileSync(absPath, 'utf8');
      if (current !== item.content) {
        throw new JoyError(
          'E_DRIFT',
          `File "${item.relPath}" has drifted from canonical spec.\n${formatSimpleDiff(item.relPath, current, item.content)}`,
          2
        );
      }
      continue;
    }

    if (exists) {
      const current = fs.readFileSync(absPath, 'utf8');
      const hasGeneratedHeader = current.startsWith(GENERATED_BANNER);
      if (item.generated && hasGeneratedHeader) {
        summary.overwritten.push(item.relPath);
        summary.diffs[item.relPath] = formatSimpleDiff(item.relPath, current, item.content);
      } else if (opts.force) {
        summary.overwritten.push(item.relPath);
        summary.diffs[item.relPath] = formatSimpleDiff(item.relPath, current, item.content);
      } else {
        throw new JoyError(
          'E_EXISTS',
          `Target file "${item.relPath}" already exists (and is not marked @generated). Pass --force to overwrite.`,
          2
        );
      }
    } else {
      summary.created.push(item.relPath);
      summary.diffs[item.relPath] = formatSimpleDiff(item.relPath, '', item.content);
    }
  }

  for (const edit of plan.edits) {
    const absPath = path.join(cwd, edit.relPath);
    const current = fs.existsSync(absPath) ? fs.readFileSync(absPath, 'utf8') : '';
    if (current !== edit.content) {
      summary.edited.push(edit.relPath);
      summary.diffs[edit.relPath] = formatSimpleDiff(edit.relPath, current, edit.content);
    }
  }

  if (opts.check || opts.dryRun) {
    return summary;
  }

  // Phase 2: Snapshot prior state for atomic rollback
  const snapshots = new Map<string, string | null>();
  for (const item of plan.creates) {
    const absPath = path.join(cwd, item.relPath);
    snapshots.set(absPath, fs.existsSync(absPath) ? fs.readFileSync(absPath, 'utf8') : null);
  }
  for (const edit of plan.edits) {
    const absPath = path.join(cwd, edit.relPath);
    snapshots.set(absPath, fs.existsSync(absPath) ? fs.readFileSync(absPath, 'utf8') : null);
  }

  // Phase 3: Write all files
  for (const item of plan.creates) {
    const absPath = path.join(cwd, item.relPath);
    fs.mkdirSync(path.dirname(absPath), { recursive: true });
    fs.writeFileSync(absPath, item.content, 'utf8');
  }
  for (const edit of plan.edits) {
    const absPath = path.join(cwd, edit.relPath);
    fs.mkdirSync(path.dirname(absPath), { recursive: true });
    fs.writeFileSync(absPath, edit.content, 'utf8');
  }

  // Phase 4: Execute verify commands; rollback on failure
  if (!opts.noVerify && opts.verifyCommands && opts.verifyCommands.length > 0) {
    for (const cmd of opts.verifyCommands) {
      try {
        execSync(cmd, { cwd, stdio: 'pipe' });
      } catch (err: unknown) {
        if (!opts.keepOnFail) {
          for (const [absPath, prevContent] of snapshots.entries()) {
            if (prevContent === null) {
              fs.rmSync(absPath, { force: true });
            } else {
              fs.writeFileSync(absPath, prevContent, 'utf8');
            }
          }
        }
        const stderr =
          err && typeof err === 'object' && 'stderr' in err && Buffer.isBuffer((err as { stderr: unknown }).stderr)
            ? ((err as { stderr: Buffer }).stderr.toString('utf8'))
            : String(err);
        throw new JoyError(
          'E_VERIFY_FAILED',
          `Verification command failed: "${cmd}" (rolled back ${snapshots.size} files)\n${stderr}`,
          1
        );
      }
    }
  }

  return summary;
}
